    if v == "no_stash":
        b.edit(b.G)
        return [f"git restore --source=stash@{{0}} {b.F}"]
    b.branch(b.F)
    if v == "branch_dirty":
        b.edit(b.F)
    return [f"git restore --source={b.br} {b.F}"]


